package com.example.riskplatform.service.cache;import lombok.RequiredArgsConstructor;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.data.redis.core.StringRedisTemplate;import org.springframework.stereotype.Service;import java.time.Duration;
@Service @RequiredArgsConstructor @ConditionalOnProperty(name="app.redis.enabled",havingValue="true")public class RedisCacheService implements CacheService{private final StringRedisTemplate redis;public String get(String k){return redis.opsForValue().get(k);}public void set(String k,String v,Duration t){redis.opsForValue().set(k,v,t);}}
